// CSD_RATIONALE_BEGIN
// This strategy aims to solve math word problems involving arithmetic operations on symbolic quantities.
// It uses a combination of constrained steps and soft constrained steps to guide the generation process towards a valid solution.
// The strategy starts with an unconstrained step to generate initial tokens, then refines them using constrained steps.
// If the current token does not lead to a valid grammar continuation, a confidence-gated step is taken.
// If the problem is deemed unsolvable due to dead-end detection, the strategy backtracks to the last valid state.
// The goal is to produce a valid mathematical expression within the given maximum steps.
// CSD_RATIONALE_END

while |generated| < maxSteps {
    if |generated| == 0 {
        var next := helpers.UnconstrainedStep(lm, prompt, generated);  // Start with an unconstrained step
    } else {
        var next, isValid := helpers.SoftConstrainedStep(lm, parser, prompt, generated, 1.0);  // Softly constrain the next token
        if !isValid {
            next, _ := helpers.ConfidenceGatedStep(lm, parser, prompt, generated);  // Use confidence gating if necessary
        }
    }
    generated := generated + [next];  // Append the new token to the generated sequence
}

if helpers.DeadEndDetection(parser, generated, 1) {  // Check for dead-end conditions
    generated := helpers.RollbackToValidPrefix(parser, generated);  // Rollback to the last valid state
}

cost := helpers.cost;  // Assign the total cost;

